FUNCTION_BLOCK FB_EthyleneRefrig_CentrifugalIGV
(*
 ===================================================================================================
 LUMINA ADVANCED PROCESS AUTOMATION & CYBER-PHYSICAL SYSTEMS ARCHITECTURE
 DOMAIN      : Petrochemical Olefins Plant - Ethylene Fractionation Refrigeration Train
 SUBSYSTEM   : Multi-Stage Centrifugal Chiller Variable Inlet Guide Vanes (IGV) & Anti-Surge Recycle
 DESIGN BASIS: API 670 5th Ed. (Machinery Protection) / ASME PTC 10 (Centrifugal Compressors)
               IEC 61508 / IEC 61511 (SIL-3 Functional Safety Compliant Automation)
 FEATURES    :
   1. 2oo3 Triple Modular Redundant (TMR) Suction Pressure Sensor Voting & Graceful Degradation
   2. Real-Gas Equation of State (EOS) for Pure Ethylene (C2H4) Cryogenic Polytropic Head
   3. Invariant Reduced-Coordinate Surge Mapping with Dynamic Lead-Lag Rate-of-Approach Derivative
   4. 2x2 MIMO Discrete State-Space Model Predictive Control (MPC) Decoupling IGV Capacity & ASV
   5. Coordinated Fast-Open Slam Anti-Surge Action with Asymmetric Slew-Rate Recovery
   6. Comprehensive ISA-18.2 Diagnostic and Fault Alarm Status Bitmasks
 ===================================================================================================
*)
VAR_INPUT
    bEnable                     : BOOL;     (* System master enable permissive command [BOOL] *)
    bTripReset                  : BOOL;     (* Operator manual trip reset and alarm unlatch pulse [BOOL] *)
    bEmergencyShutdown_ESD      : BOOL;     (* Hardwired fail-safe SIS interlock (Active LOW: FALSE=Trip) [BOOL] *)
    rSuctionPres_A_bar          : REAL;     (* Stage 1 Suction Pressure Sensor PT-101A [bar] *)
    rSuctionPres_B_bar          : REAL;     (* Stage 1 Suction Pressure Sensor PT-101B [bar] *)
    rSuctionPres_C_bar          : REAL;     (* Stage 1 Suction Pressure Sensor PT-101C [bar] *)
    rDischargePres_bar          : REAL;     (* Stage 3 Final Discharge Header Pressure Transmitter PT-104 [bar] *)
    rSuctionTemp_degC           : REAL;     (* Suction Gas Temperature Sensor TT-101 [deg C] *)
    rDischargeTemp_degC         : REAL;     (* Final Stage Discharge Gas Temperature Sensor TT-104 [deg C] *)
    rCompressorSpeed_rpm        : REAL;     (* Centrifugal Compressor Shaft Speed Sensor ST-101 [rpm] *)
    rMassFlow_kgh               : REAL;     (* Refrigerant Ethylene Mass Flow Rate FT-101 [kg/h] *)
    rDiffPresOrifice_mbar       : REAL;     (* Suction Venturi Flow Differential Pressure PDT-101 [mbar] *)
    rChilledEthyleneDemand_pct  : REAL;     (* Downstream Ethylene Fractionator Chilling Demand [% (0-100)] *)
    rGuideVaneFeedback_pct      : REAL;     (* Inlet Guide Vanes Actual Position Feedback ZT-101 [% (0-100)] *)
    rAntiSurgeValveFeedback_pct : REAL;     (* Anti-Surge Recycle Valve Position Feedback ZT-102 [% (0-100)] *)
    rLubeOilPres_bar            : REAL;     (* Compressor Bearing Lube Oil Header Pressure PT-108 [bar] *)
    rMotorCurrent_A             : REAL;     (* Main Electric Drive Motor Stator Current IT-101 [A] *)
    rCycleTime_s                : REAL;     (* PLC Deterministic Cyclic Execution Time Delta [s] (e.g. 0.010 s) *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* Compressor chiller train online and ready for load modulation [BOOL] *)
    rIGV_PositionCmd_pct        : REAL;     (* Variable Inlet Guide Vanes Target Command MV-101 [% (0=Closed, 100=Open)] *)
    rASV_PositionCmd_pct        : REAL;     (* Anti-Surge Modulating Recycle Valve Command FV-102 [% (0=Closed, 100=Open)] *)
    rSurgeMargin_pct            : REAL;     (* Dynamic Distance to Surge Limit Line (SLL) [% safety margin] *)
    rPolytropicHead_kJkg        : REAL;     (* Real-Gas Ethylene Polytropic Head Approximation Hp [kJ/kg] *)
    rCompressionRatio           : REAL;     (* Compression Ratio Rc = P_discharge / P_suction_voted [-] *)
    rGasDensity_kgm3            : REAL;     (* Calculated Suction Ethylene Vapor Density [kg/m3] *)
    rVolumetricFlow_m3h         : REAL;     (* Calculated Suction Volumetric Capacity Q_suct [m3/h] *)
    bSurgeWarningAlarm          : BOOL;     (* Surge Early Warning: Operating point crossed Surge Control Line [BOOL] *)
    bSurgeTripActive            : BOOL;     (* Surge Limit Incursion: Emergency Fast-Open Recycle Slam Active [BOOL] *)
    wDiagnosticStatusWord       : WORD;     (* Loop Health, 2oo3 Sensor Voting & Permissive Bitmask *)
    wSurgeAlarmStatusWord       : WORD;     (* Anti-Surge Controller Dynamic Mode & Alarm Bitmask *)
    iCurrentState               : INT;      (* Active Finite State Machine Operational Phase Code (0..60) *)
END_VAR

VAR
    (* --- 2oo3 Triple Modular Redundant (TMR) Sensor Voting & Health Supervision --- *)
    rVotedSuctionPres_bar       : REAL;     (* Voted Median Suction Pressure Process Variable [bar] *)
    bSensorFail_A               : BOOL;     (* Transmitter PT-101A Discrepancy / Out-of-Range Fault *)
    bSensorFail_B               : BOOL;     (* Transmitter PT-101B Discrepancy / Out-of-Range Fault *)
    bSensorFail_C               : BOOL;     (* Transmitter PT-101C Discrepancy / Out-of-Range Fault *)
    rDevAB                      : REAL;     (* Absolute Transmitter Deviation |PT-101A - PT-101B| [bar] *)
    rDevBC                      : REAL;     (* Absolute Transmitter Deviation |PT-101B - PT-101C| [bar] *)
    rDevCA                      : REAL;     (* Absolute Transmitter Deviation |PT-101C - PT-101A| [bar] *)
    rMaxAllowedSensorDev_bar    : REAL := 0.120; (* Maximum Plausible Sensor Deviation Tolerance [bar] *)

    (* --- Real-Gas Thermodynamic Parameter Constants & Working Variables (Ethylene C2H4) --- *)
    (* Molecular weight: 28.054 kg/kmol; Specific Gas Constant R = 8.31447 / 28.054 = 0.29638 kJ/(kg*K) *)
    rR_GasConstant              : REAL := 0.29638;  (* Specific gas constant for pure Ethylene [kJ/(kg*K)] *)
    rZ_Compressibility          : REAL := 0.8870;   (* Suction compressibility factor Z under cryogenic conditions [-] *)
    rIsentropicExp_k            : REAL := 1.2440;   (* Ratio of specific heats Cp/Cv for C2H4 at -35 deg C [-] *)
    rPolytropicEfficiency       : REAL := 0.8250;   (* Compressor stage nominal polytropic efficiency [-] *)
    rSuctionTemp_Kelvin         : REAL;             (* Suction Temperature in Absolute Scale [K] *)
    rDischargeTemp_Kelvin       : REAL;             (* Discharge Temperature in Absolute Scale [K] *)

    (* --- Aerodynamic Surge Coordinates & Dynamic Operating Map --- *)
    (* In invariant reduced coordinates: dP_surge = A_sll * Rc^2 + B_sll * Rc + C_sll [mbar] *)
    rCoeff_A_sll                : REAL := 15.320;   (* 2nd-order parabolic curvature coefficient for SLL *)
    rCoeff_B_sll                : REAL := 34.680;   (* 1st-order linear slope coefficient for SLL *)
    rCoeff_C_sll                : REAL := 6.150;    (* Orifice differential zero-offset constant [mbar] *)
    rDiffPres_SurgeLimit_mbar   : REAL;             (* Calculated minimum orifice differential at Surge Limit Line [mbar] *)
    rDiffPres_SurgeControl_mbar : REAL;             (* Calculated Surge Control Line (SCL = SLL * (1 + Margin)) [mbar] *)
    rSafetyMarginFactor         : REAL := 1.120;    (* 12.0% Steady-state safety buffer offset between SLL and SCL *)

    (* --- Dynamic Rate-of-Approach Anti-Surge Lead-Lag Derivative Compensator --- *)
    rDiffPres_Prev_mbar         : REAL;             (* Historical orifice differential pressure sample [mbar] *)
    rdP_dt                      : REAL;             (* Raw numerical derivative of orifice differential [mbar/s] *)
    rdP_dt_LeadLag              : REAL;             (* Phase-advanced lead-lag filtered dynamic approach rate [mbar/s] *)
    rLeadTimeConstant_s         : REAL := 0.950;    (* Anti-surge derivative lead time constant T_lead [s] *)
    rLagTimeConstant_s          : REAL := 0.150;    (* Noise suppression lag filter time constant T_lag [s] *)
    rDynamicBias_mbar           : REAL;             (* Dynamic margin expansion bias injected into control setpoint [mbar] *)
    rDynamicBiasGain            : REAL := 2.250;    (* Gain multiplier translating approach velocity to dP margin [s] *)

    (* --- Multi-Variable State-Space & Decoupled Model Predictive Control (MPC) --- *)
    (* Discrete State vector x = [x1: Suction Pres Deviation, x2: Flow Nozzle dP Deviation]^T *)
    (* Input vector u = [u1: IGV position adjustment, u2: ASV recycle position adjustment]^T *)
    (* State transition matrix A (2x2) and input matrix B (2x2) calibrated for ethylene compression *)
    rA_Matrix_11                : REAL := 0.9620;
    rA_Matrix_12                : REAL := -0.0280;
    rA_Matrix_21                : REAL := 0.0740;
    rA_Matrix_22                : REAL := 0.9120;
    rB_Matrix_11                : REAL := 0.5200;
    rB_Matrix_12                : REAL := -0.1850;
    rB_Matrix_21                : REAL := 0.0950;
    rB_Matrix_22                : REAL := 0.8400;
    rState_x1                   : REAL := 0.0;
    rState_x2                   : REAL := 0.0;
    rPredError_Pres             : REAL;
    rPredError_Flow             : REAL;

    (* --- Closed-Loop Controllers (IGV Pressure/Load PI & ASV Anti-Surge PI) --- *)
    rSuctionPresSetpoint_bar    : REAL := 1.420;    (* Stage 1 Evaporator Evacuation Pressure Target [bar] *)
    rIGV_PropGain_Kp            : REAL := 2.750;    (* IGV Proportional Control Gain *)
    rIGV_IntTime_Ti             : REAL := 16.000;   (* IGV Integral Reset Time Constant [s] *)
    rIGV_IntegralAccumulator    : REAL := 30.000;   (* IGV Anti-Windup Bumpless Integral Storage [%] *)
    rIGV_SlewRateLimit_pct_s    : REAL := 4.000;    (* Maximum allowable IGV movement speed [% / s] *)

    rASV_PropGain_Kp            : REAL := 5.800;    (* ASV Fast Proportional Anti-Surge Gain *)
    rASV_IntTime_Ti             : REAL := 2.800;    (* ASV Fast Integral Action Reset Time [s] *)
    rASV_IntegralAccumulator    : REAL := 0.000;    (* ASV Integral Storage [%] *)
    rASV_EmergencyOpenRate_pct_s: REAL := 180.000;  (* Anti-Surge Quick-Slam Fast Opening Velocity [% / s] *)
    rASV_ControlledCloseRate_pct_s : REAL := 3.500; (* Surge Recovery Slow Re-closure Velocity [% / s] *)

    (* --- Finite State Machine & Supervisory Sequencing Registers --- *)
    iFSM_State                  : INT := 0;         (* Sequence step register: 0=Safe, 10=Init, 20=Purge, 30=Ramp, 40=Run, 50=Trip, 60=Cooldown *)
    tStateTimer                 : TON;              (* Primary Sequence Transition Dwell Timer *)
    tSurgeDwellTimer            : TON;              (* Surge Recovery Settle & Re-closure Inhibit Timer *)
    tPurgeTimer                 : TON;              (* Pre-commissioning Warm-Gas Recirculation Timer *)
    bSurgeEventLatched          : BOOL := FALSE;    (* Memory latch for surge cycle detection *)

    (* --- Intermediate Numerical Registers --- *)
    rPolyExponent_m             : REAL;
    rIGV_TargetUnclamped        : REAL;
    rASV_TargetUnclamped        : REAL;
    rMaxDeltaIGV                : REAL;
    rMaxDeltaASV                : REAL;
    rPresError                  : REAL;
    rSurgeError                 : REAL;
    rSafeDeltaT                 : REAL;
END_VAR

(* ===================================================================================================
   EXECUTION ARCHITECTURE:
   SECTION 1: HARDWARE FAIL-SAFE INTERLOCKS & SAFETY INSTRUMENTED SYSTEM (SIS) TRIP OVERRIDE
   SECTION 2: 2oo3 TRIPLE MODULAR REDUNDANT (TMR) SUCTION PRESSURE VOTING & SENSOR HEALTH MATRIX
   SECTION 3: REAL-GAS EQUATION OF STATE (EOS) & COMPRESSOR POLYTROPIC HEAD CALCULATION
   SECTION 4: REDUCED COORDINATE SURGE MAPPING & ADVANCED LEAD-LAG APPROACH RATE ESTIMATION
   SECTION 5: MULTI-STAGE FINITE STATE MACHINE (FSM) SEQUENCING & CAPACITY DECOUPLING
   SECTION 6: ADVANCED MULTI-VARIABLE MPC / PI CONTROL WITH ANTI-WINDUP & SLEW-RATE LIMITING
   SECTION 7: DIAGNOSTIC & ALARM STATUS WORD PACKING
   =================================================================================================== *)

(* --- SECTION 1: HARDWARE FAIL-SAFE INTERLOCKS & SIS TRIP OVERRIDE --- *)
(* Hardware Emergency Shutdown (ESD) is active-low: False represents a broken safety loop or trip *)
IF (NOT bEmergencyShutdown_ESD) THEN
    iFSM_State := 0; (* Direct transition to SAFE PARK / ESD DE-ENERGIZED State *)
    bSystemReady := FALSE;
    bSurgeTripActive := TRUE;
    rIGV_PositionCmd_pct := 0.0;    (* Spring-return close IGV to isolate compressor suction *)
    rASV_PositionCmd_pct := 100.0;  (* Air-to-close fail-open ASV: Spring-snap 100% full recycle dump *)
    rIGV_IntegralAccumulator := 0.0;
    rASV_IntegralAccumulator := 100.0;
    wDiagnosticStatusWord := 16#8001; (* Bit 15: Master Trip Active, Bit 0: Hardware SIS ESD Tripped *)
    wSurgeAlarmStatusWord := 16#8000; (* Bit 15: Emergency Quick Open Commanded *)
    iCurrentState := iFSM_State;
    RETURN;
END_IF;

(* Protect execution time delta against division by zero and excessive time jitter *)
IF (rCycleTime_s < 0.001) THEN
    rSafeDeltaT := 0.001;
ELSIF (rCycleTime_s > 0.100) THEN
    rSafeDeltaT := 0.100;
ELSE
    rSafeDeltaT := rCycleTime_s;
END_IF;

(* --- SECTION 2: 2oo3 TMR SUCTION PRESSURE VOTING & SENSOR HEALTH MATRIX --- *)
(* Calculate cross-sensor differential spreads *)
rDevAB := ABS(rSuctionPres_A_bar - rSuctionPres_B_bar);
rDevBC := ABS(rSuctionPres_B_bar - rSuctionPres_C_bar);
rDevCA := ABS(rSuctionPres_C_bar - rSuctionPres_A_bar);

(* Transmitter plausibility limits for cryogenic ethylene refrigeration: 0.25 bar (deep vacuum) to 7.50 bar *)
bSensorFail_A := (rSuctionPres_A_bar < 0.25) OR (rSuctionPres_A_bar > 7.50) OR ((rDevAB > rMaxAllowedSensorDev_bar) AND (rDevCA > rMaxAllowedSensorDev_bar));
bSensorFail_B := (rSuctionPres_B_bar < 0.25) OR (rSuctionPres_B_bar > 7.50) OR ((rDevAB > rMaxAllowedSensorDev_bar) AND (rDevBC > rMaxAllowedSensorDev_bar));
bSensorFail_C := (rSuctionPres_C_bar < 0.25) OR (rSuctionPres_C_bar > 7.50) OR ((rDevBC > rMaxAllowedSensorDev_bar) AND (rDevCA > rMaxAllowedSensorDev_bar));

(* Dynamic Median Selection and Graceful Degradation Logic *)
IF (NOT bSensorFail_A) AND (NOT bSensorFail_B) AND (NOT bSensorFail_C) THEN
    (* All 3 channels fully valid: Mid-Value Voting (Median Selection) *)
    IF ((rSuctionPres_A_bar >= rSuctionPres_B_bar) AND (rSuctionPres_A_bar <= rSuctionPres_C_bar)) OR 
       ((rSuctionPres_A_bar <= rSuctionPres_B_bar) AND (rSuctionPres_A_bar >= rSuctionPres_C_bar)) THEN
        rVotedSuctionPres_bar := rSuctionPres_A_bar;
    ELSIF ((rSuctionPres_B_bar >= rSuctionPres_A_bar) AND (rSuctionPres_B_bar <= rSuctionPres_C_bar)) OR 
          ((rSuctionPres_B_bar <= rSuctionPres_A_bar) AND (rSuctionPres_B_bar >= rSuctionPres_C_bar)) THEN
        rVotedSuctionPres_bar := rSuctionPres_B_bar;
    ELSE
        rVotedSuctionPres_bar := rSuctionPres_C_bar;
    END_IF;
    wDiagnosticStatusWord := wDiagnosticStatusWord AND 16#FFF0; (* Clear sensor degradation bits *)

ELSIF bSensorFail_A AND (NOT bSensorFail_B) AND (NOT bSensorFail_C) THEN
    (* PT-101A degraded: Average channels B and C *)
    rVotedSuctionPres_bar := (rSuctionPres_B_bar + rSuctionPres_C_bar) * 0.50;
    wDiagnosticStatusWord := (wDiagnosticStatusWord AND 16#FFF0) OR 16#0002; (* Channel A degraded *)

ELSIF bSensorFail_B AND (NOT bSensorFail_A) AND (NOT bSensorFail_C) THEN
    (* PT-101B degraded: Average channels A and C *)
    rVotedSuctionPres_bar := (rSuctionPres_A_bar + rSuctionPres_C_bar) * 0.50;
    wDiagnosticStatusWord := (wDiagnosticStatusWord AND 16#FFF0) OR 16#0004; (* Channel B degraded *)

ELSIF bSensorFail_C AND (NOT bSensorFail_A) AND (NOT bSensorFail_B) THEN
    (* PT-101C degraded: Average channels A and B *)
    rVotedSuctionPres_bar := (rSuctionPres_A_bar + rSuctionPres_B_bar) * 0.50;
    wDiagnosticStatusWord := (wDiagnosticStatusWord AND 16#FFF0) OR 16#0008; (* Channel C degraded *)

ELSE
    (* Multiple sensor faults: High-select conservative fallback to protect against compressor surge *)
    rVotedSuctionPres_bar := MAX(rSuctionPres_A_bar, MAX(rSuctionPres_B_bar, rSuctionPres_C_bar));
    wDiagnosticStatusWord := (wDiagnosticStatusWord AND 16#FFF0) OR 16#000E; (* Dual/Triple Sensor Failure *)
END_IF;

(* Bound voted suction pressure to safe mechanical limits *)
IF (rVotedSuctionPres_bar < 0.25) THEN
    rVotedSuctionPres_bar := 0.25;
END_IF;

(* --- SECTION 3: REAL-GAS EQUATION OF STATE (EOS) & COMPRESSOR POLYTROPIC HEAD --- *)
rSuctionTemp_Kelvin := rSuctionTemp_degC + 273.15;
IF (rSuctionTemp_Kelvin < 160.0) THEN
    rSuctionTemp_Kelvin := 160.0; (* Mechanical limit: -113 deg C ethylene crystallization boundary *)
END_IF;

rDischargeTemp_Kelvin := rDischargeTemp_degC + 273.15;
rCompressionRatio := rDischargePres_bar / rVotedSuctionPres_bar;
IF (rCompressionRatio < 1.05) THEN
    rCompressionRatio := 1.05;
END_IF;

(* Polytropic exponent calculation: m = (k - 1) / (k * eta_poly) *)
rPolyExponent_m := (rIsentropicExp_k - 1.0) / (rIsentropicExp_k * rPolytropicEfficiency);
IF (rPolyExponent_m < 0.05) THEN
    rPolyExponent_m := 0.05;
END_IF;

(* Polytropic Head: Hp = (Z * R * T_suction / m) * [ (P_discharge / P_suction)^m - 1 ] [kJ/kg] *)
rPolytropicHead_kJkg := ((rZ_Compressibility * rR_GasConstant * rSuctionTemp_Kelvin) / rPolyExponent_m)
                        * (EXPT(rCompressionRatio, rPolyExponent_m) - 1.0);

(* Ethylene Density EOS: rho = P_suct [kPa] / (Z * R * T_suct [K]) *)
rGasDensity_kgm3 := (rVotedSuctionPres_bar * 100.0) / (rZ_Compressibility * rR_GasConstant * rSuctionTemp_Kelvin);
IF (rGasDensity_kgm3 > 0.08) THEN
    rVolumetricFlow_m3h := rMassFlow_kgh / rGasDensity_kgm3;
ELSE
    rVolumetricFlow_m3h := 0.0;
END_IF;

(* --- SECTION 4: REDUCED COORDINATE SURGE MAPPING & LEAD-LAG APPROACH RATE --- *)
(* Surge Limit Line (SLL) parabolic polynomial in reduced coordinates *)
rDiffPres_SurgeLimit_mbar := (rCoeff_A_sll * (rCompressionRatio * rCompressionRatio))
                           + (rCoeff_B_sll * rCompressionRatio)
                           + rCoeff_C_sll;

(* Surge Control Line (SCL) incorporating 12% steady-state safety margin *)
rDiffPres_SurgeControl_mbar := rDiffPres_SurgeLimit_mbar * rSafetyMarginFactor;

(* Anti-Surge Lead-Lag Rate-of-Approach Compensator *)
rdP_dt := (rDiffPresOrifice_mbar - rDiffPres_Prev_mbar) / rSafeDeltaT;
rDiffPres_Prev_mbar := rDiffPresOrifice_mbar;

(* Discrete 1st-order Lead-Lag algorithm: compensates for valve opening latency and sensor lag *)
rdP_dt_LeadLag := rdP_dt_LeadLag + (rSafeDeltaT / (rLagTimeConstant_s + rSafeDeltaT))
                  * (rLeadTimeConstant_s * rdP_dt - rdP_dt_LeadLag);

(* Dynamic Bias injection: Expands safety margin when operating point rapidly decelerates toward surge *)
IF (rdP_dt_LeadLag < 0.0) THEN
    rDynamicBias_mbar := ABS(rdP_dt_LeadLag) * rDynamicBiasGain;
ELSE
    rDynamicBias_mbar := 0.0;
END_IF;

(* Distance to Surge Limit Line (Surge Margin Percentage) *)
IF (rDiffPres_SurgeLimit_mbar > 0.50) THEN
    rSurgeMargin_pct := ((rDiffPresOrifice_mbar - rDiffPres_SurgeLimit_mbar) / rDiffPres_SurgeLimit_mbar) * 100.0;
ELSE
    rSurgeMargin_pct := 100.0;
END_IF;

(* Surge Warning & Safety Action Triggers *)
bSurgeWarningAlarm := (rDiffPresOrifice_mbar <= (rDiffPres_SurgeControl_mbar + rDynamicBias_mbar));
bSurgeTripActive   := (rDiffPresOrifice_mbar <= (rDiffPres_SurgeLimit_mbar + 1.50)) OR (rSurgeMargin_pct < 2.50);

(* --- SECTION 5: MULTI-STAGE FINITE STATE MACHINE (FSM) SEQUENCING --- *)
CASE iFSM_State OF

    0: (* STATE 0: SAFE PARK / DE-ENERGIZED / ESD SHUTDOWN *)
        bSystemReady := FALSE;
        rIGV_TargetUnclamped := 0.0;
        rASV_TargetUnclamped := 100.0;
        rIGV_IntegralAccumulator := 0.0;
        rASV_IntegralAccumulator := 100.0;
        bSurgeEventLatched := FALSE;
        tStateTimer(IN := FALSE, PT := T#5S);

        IF bEnable AND bEmergencyShutdown_ESD AND bTripReset THEN
            iFSM_State := 10; (* Transition to Pre-Check Initialization *)
        END_IF;

    10: (* STATE 10: TMR SENSOR VALIDATION & COMPRESSOR PERMISSIVE VERIFICATION *)
        bSystemReady := FALSE;
        rIGV_TargetUnclamped := 0.0;
        rASV_TargetUnclamped := 100.0;
        tStateTimer(IN := TRUE, PT := T#3S);

        (* Require valid suction pressure, compressor shaft turning above 2500 rpm, and no sensor blackout *)
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE, PT := T#3S);
            IF (rCompressorSpeed_rpm >= 2500.0) AND (rLubeOilPres_bar >= 2.50) AND (NOT (bSensorFail_A AND bSensorFail_B AND bSensorFail_C)) THEN
                iFSM_State := 20; (* Advance to Warm-Gas Recycle Purge *)
            ELSE
                wDiagnosticStatusWord := wDiagnosticStatusWord OR 16#0100; (* Permissive wait warning *)
            END_IF;
        END_IF;

    20: (* STATE 20: WARM-GAS RECYCLE & CONDENSATE DRY-OUT PURGE *)
        bSystemReady := FALSE;
        rIGV_TargetUnclamped := 5.0; (* Crack IGV slightly to prevent vacuum sealing *)
        rASV_TargetUnclamped := 100.0; (* Maintain 100% full recycle loop *)
        tPurgeTimer(IN := TRUE, PT := T#15S);

        IF tPurgeTimer.Q THEN
            tPurgeTimer(IN := FALSE, PT := T#15S);
            IF (rDischargeTemp_degC >= -20.0) AND (rCompressorSpeed_rpm >= 6000.0) THEN
                iFSM_State := 30; (* Advance to Speed Acceleration & Pre-Chill *)
            END_IF;
        END_IF;

    30: (* STATE 30: SPEED ACCELERATION & PRE-CHILL CONDENSING *)
        bSystemReady := FALSE;
        rIGV_TargetUnclamped := 15.0; (* Pre-position IGV to minimum chilling line *)
        rASV_TargetUnclamped := 65.0; (* Ramp down recycle valve slowly to build stage compression ratio *)
        tStateTimer(IN := TRUE, PT := T#10S);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE, PT := T#10S);
            IF (rCompressionRatio >= 2.10) AND (rSurgeMargin_pct >= 18.0) THEN
                iFSM_State := 40; (* Enter Active Full Modulation State *)
            END_IF;
        END_IF;

    40: (* STATE 40: ACTIVE DUAL-DECOUPLED CAPACITY & ANTI-SURGE MODULATION *)
        bSystemReady := TRUE;

        (* Multi-Variable State-Space Observer Update: x(k+1) = A*x(k) + B*u(k) *)
        rPredError_Pres := rSuctionPresSetpoint_bar - rVotedSuctionPres_bar;
        rPredError_Flow := rDiffPresOrifice_mbar - (rDiffPres_SurgeControl_mbar + rDynamicBias_mbar);

        rState_x1 := (rA_Matrix_11 * rState_x1) + (rA_Matrix_12 * rState_x2) 
                   + (rB_Matrix_11 * (rGuideVaneFeedback_pct * 0.01)) + (rB_Matrix_12 * (rAntiSurgeValveFeedback_pct * 0.01));
        rState_x2 := (rA_Matrix_21 * rState_x1) + (rA_Matrix_22 * rState_x2) 
                   + (rB_Matrix_21 * (rGuideVaneFeedback_pct * 0.01)) + (rB_Matrix_22 * (rAntiSurgeValveFeedback_pct * 0.01));

        (* Capacity Loop (IGV): Regulate Suction Pressure & Chilled Demand Feedforward *)
        rPresError := rSuctionPresSetpoint_bar - rVotedSuctionPres_bar;
        rIGV_IntegralAccumulator := rIGV_IntegralAccumulator + ((rIGV_PropGain_Kp / rIGV_IntTime_Ti) * rPresError * rSafeDeltaT);

        (* Anti-windup clamping for IGV integral action *)
        IF (rIGV_IntegralAccumulator > 100.0) THEN
            rIGV_IntegralAccumulator := 100.0;
        ELSIF (rIGV_IntegralAccumulator < 0.0) THEN
            rIGV_IntegralAccumulator := 0.0;
        END_IF;

        (* IGV Target: Feedback + Integral + Feedforward load demand *)
        rIGV_TargetUnclamped := (rIGV_PropGain_Kp * rPresError) + rIGV_IntegralAccumulator + (rChilledEthyleneDemand_pct * 0.45);

        (* Anti-Surge Loop (ASV): Fast PI tracking distance to Surge Control Line *)
        rSurgeError := (rDiffPres_SurgeControl_mbar + rDynamicBias_mbar) - rDiffPresOrifice_mbar;

        IF (rSurgeError > 0.0) THEN
            (* Operating inside safety boundary: Fast integral accumulation *)
            rASV_IntegralAccumulator := rASV_IntegralAccumulator + ((rASV_PropGain_Kp / rASV_IntTime_Ti) * rSurgeError * rSafeDeltaT);
        ELSE
            (* Safe operating point: Slow controlled reset dissipation *)
            rASV_IntegralAccumulator := rASV_IntegralAccumulator + ((0.50 * rASV_PropGain_Kp / rASV_IntTime_Ti) * rSurgeError * rSafeDeltaT);
        END_IF;

        IF (rASV_IntegralAccumulator > 100.0) THEN
            rASV_IntegralAccumulator := 100.0;
        ELSIF (rASV_IntegralAccumulator < 0.0) THEN
            rASV_IntegralAccumulator := 0.0;
        END_IF;

        IF (rSurgeError > 0.0) THEN
            rASV_TargetUnclamped := (rASV_PropGain_Kp * rSurgeError) + rASV_IntegralAccumulator;
        ELSE
            rASV_TargetUnclamped := rASV_IntegralAccumulator;
        END_IF;

        (* Coordinated Override: If ASV opens > 25%, throttle back IGV to reduce aerodynamic load *)
        IF (rAntiSurgeValveFeedback_pct > 25.0) THEN
            rIGV_TargetUnclamped := rIGV_TargetUnclamped - ((rAntiSurgeValveFeedback_pct - 25.0) * 0.75);
        END_IF;

        (* Surge Trip Event Trigger *)
        IF bSurgeTripActive THEN
            bSurgeEventLatched := TRUE;
            iFSM_State := 50; (* Enter Emergency Anti-Surge Slam State *)
        END_IF;

        (* Normal Stop Command Transition *)
        IF (NOT bEnable) THEN
            iFSM_State := 60; (* Controlled Deceleration *)
        END_IF;

    50: (* STATE 50: SURGE DETECTED - RAPID OPEN OVERRIDE (OPEN SLAM) *)
        bSystemReady := FALSE;
        rASV_TargetUnclamped := 100.0; (* Instantaneous 100% full recycle dump *)
        rIGV_TargetUnclamped := 10.0;  (* Clamp IGV to minimum bypass *)
        rASV_IntegralAccumulator := 85.0; (* Pre-charge integral to prevent rapid re-close *)
        wSurgeAlarmStatusWord := wSurgeAlarmStatusWord OR 16#0040; (* Surge Slam Active *)

        tSurgeDwellTimer(IN := TRUE, PT := T#8S);
        IF tSurgeDwellTimer.Q AND (rSurgeMargin_pct >= 22.0) THEN
            tSurgeDwellTimer(IN := FALSE, PT := T#8S);
            IF bTripReset THEN
                bSurgeEventLatched := FALSE;
                iFSM_State := 40; (* Graceful recovery to active modulation *)
            END_IF;
        END_IF;

    60: (* STATE 60: CONTROLLED DECELERATION & SAFE VENT PARK *)
        bSystemReady := FALSE;
        rIGV_TargetUnclamped := 0.0;
        rASV_TargetUnclamped := 100.0;
        tStateTimer(IN := TRUE, PT := T#12S);

        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE, PT := T#12S);
            iFSM_State := 0; (* Return to Safe Park *)
        END_IF;

ELSE
    iFSM_State := 0; (* Default catch-all fail-safe state *)
END_CASE;

(* --- SECTION 6: ACTUATOR SLEW-RATE LIMITING & SATURATION CLAMPING --- *)
(* IGV Slew Rate Limiter *)
rMaxDeltaIGV := rIGV_SlewRateLimit_pct_s * rSafeDeltaT;
IF ((rIGV_TargetUnclamped - rIGV_PositionCmd_pct) > rMaxDeltaIGV) THEN
    rIGV_PositionCmd_pct := rIGV_PositionCmd_pct + rMaxDeltaIGV;
ELSIF ((rIGV_PositionCmd_pct - rIGV_TargetUnclamped) > rMaxDeltaIGV) THEN
    rIGV_PositionCmd_pct := rIGV_PositionCmd_pct - rMaxDeltaIGV;
ELSE
    rIGV_PositionCmd_pct := rIGV_TargetUnclamped;
END_IF;

(* Clamp IGV output to mechanical boundaries: 0.0% to 100.0% *)
IF (rIGV_PositionCmd_pct > 100.0) THEN
    rIGV_PositionCmd_pct := 100.0;
ELSIF (rIGV_PositionCmd_pct < 0.0) THEN
    rIGV_PositionCmd_pct := 0.0;
END_IF;

(* ASV Asymmetric Slew Rate Limiter (Rapid Fast Opening, Controlled Slow Closing) *)
IF (rASV_TargetUnclamped > rASV_PositionCmd_pct) THEN
    (* Opening direction: allow high velocity up to 180 %/s *)
    rMaxDeltaASV := rASV_EmergencyOpenRate_pct_s * rSafeDeltaT;
    IF ((rASV_TargetUnclamped - rASV_PositionCmd_pct) > rMaxDeltaASV) THEN
        rASV_PositionCmd_pct := rASV_PositionCmd_pct + rMaxDeltaASV;
    ELSE
        rASV_PositionCmd_pct := rASV_TargetUnclamped;
    END_IF;
ELSE
    (* Closing direction: tightly rate-limited to avoid precipitating aerodynamic surge *)
    rMaxDeltaASV := rASV_ControlledCloseRate_pct_s * rSafeDeltaT;
    IF ((rASV_PositionCmd_pct - rASV_TargetUnclamped) > rMaxDeltaASV) THEN
        rASV_PositionCmd_pct := rASV_PositionCmd_pct - rMaxDeltaASV;
    ELSE
        rASV_PositionCmd_pct := rASV_TargetUnclamped;
    END_IF;
END_IF;

(* Clamp ASV output to physical valve travel: 0.0% to 100.0% *)
IF (rASV_PositionCmd_pct > 100.0) THEN
    rASV_PositionCmd_pct := 100.0;
ELSIF (rASV_PositionCmd_pct < 0.0) THEN
    rASV_PositionCmd_pct := 0.0;
END_IF;

(* --- SECTION 7: DIAGNOSTIC BITMASK & ALARM WORD ENCODING --- *)
wSurgeAlarmStatusWord := 16#0000;
IF bSurgeWarningAlarm THEN
    wSurgeAlarmStatusWord := wSurgeAlarmStatusWord OR 16#0001; (* Bit 0: Surge Proximity Warning *)
END_IF;
IF bSurgeTripActive THEN
    wSurgeAlarmStatusWord := wSurgeAlarmStatusWord OR 16#0002; (* Bit 1: Active Surge Incursion *)
END_IF;
IF bSurgeEventLatched THEN
    wSurgeAlarmStatusWord := wSurgeAlarmStatusWord OR 16#0004; (* Bit 2: Surge Event Latched *)
END_IF;
IF (rdP_dt_LeadLag < -5.0) THEN
    wSurgeAlarmStatusWord := wSurgeAlarmStatusWord OR 16#0008; (* Bit 3: Fast Rate-of-Approach Dynamic Trigger *)
END_IF;
IF (rSurgeMargin_pct < 10.0) THEN
    wSurgeAlarmStatusWord := wSurgeAlarmStatusWord OR 16#0010; (* Bit 4: Margin Under Critical 10% *)
END_IF;

(* Update System Output Status Register *)
iCurrentState := iFSM_State;

END_FUNCTION_BLOCK
